mapper.select:
SELECT OUT_TB.* FROM ( SELECT IN_TB.* , ROW_NUMBER() OVER (ORDER BY IN_TB.EMP_ID ) AS RNUM FROM ( SELECT A.EMP_ID ,A.CUST_CODE ,A.EMP_GRADE ,A.USE_TYPE ,A.JOIN_DATE ,A.EMP_NAME ,A.DEPT1_NM ,A.DEPT2_NM ,A.DEPT_GRADE_NM ,A.EMAIL ,A.TEL_NO ,A.REG_ID ,A.REG_DATE ,A.UPD_ID ,A.UPD_DATE ,A.INOUT_GUBUN ,A.EACH_EMP_ID ,A.GROUP_EMP_ID ,A.APPROVAL_AUTH ,B.CUST_KOR_NAME ,(SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='COMMON' AND P_CODE ='CD01' AND CODE = A.EMP_GRADE) EMP_GRADE_NAME ,(SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='COMMON' AND P_CODE ='CD02' AND CODE = A.USE_TYPE) USE_TYPE_NAME FROM CRM_CUST_EMP A INNER JOIN CRM_CUST_MGT B ON A.CUST_CODE = B.ERP_CODE ) IN_TB WHERE 1=1
) OUT_TB
WHERE RNUM BETWEEN #{startRow} AND #{endRow}
ORDER BY RNUM DESC

