	,DEPT1_NM = #{dept1_nm, jdbcType=VARCHAR}
	,DEPT2_NM = #{dept2_nm, jdbcType=VARCHAR}
	,DEPT_GRADE_NM = #{dept_grade_nm, jdbcType=VARCHAR}			
	,EMAIL = #{email, jdbcType=VARCHAR}
	,TEL_NO = #{tel_no, jdbcType=VARCHAR}		
	,UPD_ID = #{reg_id, jdbcType=VARCHAR}		
	,UPD_DATE = SYSDATE
	,APPROVAL_AUTH =  #{approval_auth, jdbcType=VARCHAR}
	,COMPANY_NO = #{company_no, jdbcType=VARCHAR}	
	,LOCK_YN = #{lock_yn, jdbcType=VARCHAR} /* 로그인 LOCK 여부 */
	,LOGIN_F_CNT = DECODE( #{lock_yn}, 'N', 0, LOGIN_F_CNT )  /* 로그인 LOCK해제시 실패로그인횟수 초기화 */   


	, PASS = #{pass, jdbcType=VARCHAR}	
	, PASS_CHG_DATE = SYSDATE	


WHERE 
	EMP_ID = #{emp_id, jdbcType=VARCHAR}

mapper.select:
SELECT IN_TB.* FROM( SELECT SEQ , CUST_KOR_NAME , CUST_ADDRESS , CUST_NO , ERP_CODE, CEO , (SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='CUST' AND P_CODE ='CD01' AND CODE = CUST_GUBUN) AS CUST_GUBUN_NM, ROW_NUMBER() OVER (ORDER BY A.SEQ ) AS RNUM FROM CRM_CUST_MGT A WHERE 1=1
AND UPPER(A.CUST_KOR_NAME) LIKE '%'|| UPPER(#{search_text}) ||'%'
) IN_TB WHERE RNUM BETWEEN #{startRow, jdbcType=INTEGER} AND #{endRow, jdbcType=INTEGER} ORDER BY RNUM DESC

SELECT OUT_TB.* FROM ( SELECT IN_TB.* , ROW_NUMBER() OVER (ORDER BY IN_TB.EMP_NO ) AS RNUM FROM ( SELECT A.EMP_NO ,A.EMP_NM ,A.DEPT1_CD ,A.DEPT2_CD ,A.DEPT_GRADE_CD ,A.E_MAIL ,A.MOBILE_NO ,A.RETIRE_DATE ,A.REG_DATE ,A.REG_ID ,A.UPD_DATE ,A.UPD_ID ,A.DEPT1_NM ,A.DEPT2_NM ,A.DEPT_GRADE_NM ,A.USE_YN ,A.COMPANY_NO FROM CRM_EMP_MGT A ) IN_TB WHERE 1=1
) OUT_TB
WHERE RNUM BETWEEN #{startRow} AND #{endRow}
ORDER BY RNUM DESC

