SELECT COUNT(IN_TB.EMP_ID) FROM ( SELECT A.EMP_ID , A.EMP_GRADE , A.EMP_NAME , A.DEPT2_NM , A.DEPT_GRADE_NM , A.TEL_NO , A.EMAIL , A.USE_TYPE , A.JOIN_DATE , A.CUST_CODE, A.APPROVAL_AUTH FROM CRM_CUST_EMP A WHERE A.CUST_CODE = #{erp_code, jdbcType=VARCHAR}
AND A.USE_TYPE = #{search_type1}
AND A.EMP_GRADE = #{search_type2}
AND A.APPROVAL_AUTH = #{search_type3}
AND ( UPPER(A.EMP_ID) LIKE '%'|| UPPER(#{search_text}) ||'%' OR UPPER(A.EMP_NAME) LIKE '%'|| UPPER(#{search_text}) ||'%' OR UPPER(A.DEPT2_NM) LIKE '%'|| UPPER(#{search_text}) ||'%' )
) IN_TB

SELECT IN_TB.* FROM ( SELECT A.EMP_ID , A.EMP_GRADE , A.EMP_NAME , A.DEPT2_NM , A.DEPT_GRADE_NM , A.TEL_NO , A.EMAIL , A.USE_TYPE , A.JOIN_DATE , A.CUST_CODE , A.APPROVAL_AUTH, (SELECT CODE_NAME FROM CRM_CODE_DETAIL Z WHERE CODE_GROUP='COMMON' AND P_CODE ='CD02' AND CODE = A.USE_TYPE) USE_TYPE_NAME , ROW_NUMBER() OVER (ORDER BY A.EMP_ID ) AS RNUM FROM CRM_CUST_EMP A WHERE A.CUST_CODE = #{erp_code, jdbcType=VARCHAR}
AND A.USE_TYPE = #{search_type1}
AND A.EMP_GRADE = #{search_type2}
AND A.APPROVAL_AUTH = #{search_type3}
AND ( UPPER(A.EMP_ID) LIKE '%'|| UPPER(#{search_text}) ||'%' OR UPPER(A.EMP_NAME) LIKE '%'|| UPPER(#{search_text}) ||'%' OR UPPER(A.DEPT2_NM) LIKE '%'|| UPPER(#{search_text}) ||'%' )
) IN_TB WHERE RNUM BETWEEN #{startRow, jdbcType=INTEGER} AND #{endRow, jdbcType=INTEGER} ORDER BY RNUM DESC

mapper.insert:
    /* 어드민(직원) 비밀번호 정책 패스워드변경 히스토리  2020.09.15. */	

