            PASS_CHG_DATE,  EMP_NO,    PASS
        ) VALUES (
            SYSDATE,    #{emp_no, jdbcType=VARCHAR},    #{pass, jdbcType=VARCHAR} 
        )

    /* 고객사 회원정보 비밀번호 정책 패스워드변경 히스토리  2020.09.15. */	

		INSERT INTO CRM_CUST_EMP_PASS_HIS (
            PASS_CHG_DATE,  EMP_ID,    PASS
        ) VALUES (
            SYSDATE,    #{emp_id, jdbcType=VARCHAR},    #{pass, jdbcType=VARCHAR} 
