mapper.update:
    /* 어드민(직원) 비밀번호 정책  로그인시 비밀번호 오류횟수 UPDATE  2020.09.15. */

		UPDATE CRM_EMP_MGT
		SET    LOGIN_F_CNT = nvl(LOGIN_F_CNT,0) + 1
		      ,LOCK_YN = CASE WHEN (nvl(LOGIN_F_CNT,0) + 1) >= (SELECT TO_NUMBER(VAL1) FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'COMMON' AND P_CODE = 'CD10' AND CODE = 'C002') THEN 'Y' ELSE NVL(LOCK_YN,'N') END /* 로그인LOCK여부 Y처리 */ 
		WHERE  EMP_NO = #{emp_no, jdbcType=VARCHAR}

    /* 고객사 회원정보 비밀번호 정책  로그인시 비밀번호 오류횟수 UPDATE  2020.09.15. */ 

		UPDATE CRM_CUST_EMP 
		SET    LOGIN_F_CNT = nvl(LOGIN_F_CNT,0) + 1  
		      ,LOCK_YN = CASE WHEN (nvl(LOGIN_F_CNT,0) + 1) >= (SELECT TO_NUMBER(VAL1) FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'COMMON' AND P_CODE = 'CD10' AND CODE = 'C002') THEN 'Y' ELSE NVL(LOCK_YN,'N') END /* 로그인LOCK여부 Y처리 */ 
		WHERE  EMP_ID = #{emp_id, jdbcType=VARCHAR}

    /* 어드민(직원) 비밀번호 정책  로그인 성공시 비밀번호 오류횟수 초기화 UPDATE  2020.09.22. */

		UPDATE CRM_EMP_MGT
		SET    LOGIN_F_CNT = 0  /* 비밀번호 오류횟수 초기화 */
		      ,LOCK_YN = 'N'    /* 로그인LOCK여부 N 해제 */ 
		WHERE  EMP_NO = #{emp_no, jdbcType=VARCHAR}

    /* 고객사 회원정보 비밀번호 정책  로그인 성공시 비밀번호 오류횟수 초기화 UPDATE  2020.09.22. */ 

		UPDATE CRM_CUST_EMP 
		SET    LOGIN_F_CNT = 0  /* 비밀번호 오류횟수 초기화 */
		      ,LOCK_YN = 'N'    /* 로그인LOCK여부 N 해제 */ 
		WHERE  EMP_ID = #{emp_id, jdbcType=VARCHAR}

mapper.select:
    /* 어드민(직원) 비밀번호 정책 로그인시 비밀번호 오류횟수 SELECT  2020.09.18. */	

		SELECT nvl(LOGIN_F_CNT,0) AS LOGIN_F_CNT 	
          FROM CRM_EMP_MGT  
         WHERE EMP_NO = #{emp_no, jdbcType=VARCHAR}

    /* 고객사 비밀번호 정책 로그인시 비밀번호 오류횟수 SELECT  2020.09.18. */	

		SELECT nvl(LOGIN_F_CNT,0) AS LOGIN_F_CNT 	
          FROM CRM_CUST_EMP 
         WHERE EMP_ID = #{emp_id, jdbcType=VARCHAR}

    /* 어드민(직원) 비밀번호 정책 로그인LOCK처리(Y) 로그인제한 체크  2020.09.16. */	

		SELECT NVL(A.LOCK_YN,'N') AS lock_yn 	
          FROM CRM_EMP_MGT A 
         WHERE A.EMP_NO = #{emp_no, jdbcType=VARCHAR}

    /* 어드민(직원) 비밀번호 정책 (C001 정책일수) 초과(Y) 체크  2020.09.15. */	

		SELECT CASE WHEN TRUNC(SYSDATE - (A.PASS_CHG_DATE + 1),0) > TO_NUMBER(Z.VAL1) THEN 'Y' ELSE 'N' END AS pass_policy1
		      ,Z.VAL1 AS policy1_val 
          FROM CRM_EMP_MGT A,    
               (SELECT VAL1 FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'COMMON' AND P_CODE = 'CD10' AND CODE = 'C001') Z      
         WHERE A.EMP_NO = #{emp_no, jdbcType=VARCHAR}

    /* 어드민(직원) 비밀번호 정책 (C002 오류횟수제한) 로그인시 비밀번호 오류횟수제한(Y) 체크  2020.09.15. */	

		SELECT CASE WHEN A.LOGIN_F_CNT >= TO_NUMBER(Z.VAL1) THEN 'Y' ELSE 'N' END AS pass_policy2 
		      ,Z.VAL1 AS policy2_val 		
          FROM CRM_EMP_MGT A,     
               (SELECT VAL1 FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'COMMON' AND P_CODE = 'CD10' AND CODE = 'C002') Z      
         WHERE A.EMP_NO = #{emp_no, jdbcType=VARCHAR}

    /* 어드민(직원) 비밀번호 정책 (C003 동일비번체크제한) 동일 비밀번호 체크제한(Y) 체크  변경 2024.03.19. */	

			SELECT CASE WHEN COUNT(*) > 0 THEN 'Y' ELSE 'N' END AS pass_policy3, MAX((SELECT VAL1 FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'COMMON' AND P_CODE = 'CD10' AND CODE = 'C003')) AS policy3_val
			FROM (
    			SELECT PASS
    			FROM CRM_EMP_MGT_PASS_HIS
    			WHERE EMP_NO = #{emp_no, jdbcType=VARCHAR}
      			AND ROWNUM <= (SELECT VAL1 FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'COMMON' AND P_CODE = 'CD10' AND CODE = 'C003')
    			ORDER BY PASS_CHG_DATE DESC
			)
			WHERE PASS = #{pass, jdbcType=VARCHAR}

    /* 어드민(직원) 비밀번호 정책 (C003 동일비번체크제한) 동일 비밀번호 체크제한(Y) 체크건수  2020.09.15. */	

		SELECT COUNT(*)
          FROM CRM_EMP_MGT_PASS_HIS  
         WHERE EMP_NO = #{emp_no, jdbcType=VARCHAR}
           AND PASS = #{pass, jdbcType=VARCHAR}

    /* 어드민(직원) 비밀번호 정책 아이디 존재유무 체크건수  2020.09.15. */	

		SELECT COUNT(*) 
          FROM CRM_EMP_MGT
         WHERE EMP_NO = #{emp_no, jdbcType=VARCHAR}

    /* 어드민(직원) 비밀번호 정책 아이디/비번 체크건수  2020.09.15. */	

		SELECT COUNT(*) 
          FROM CRM_EMP_MGT
         WHERE EMP_NO = #{emp_no, jdbcType=VARCHAR}  
           AND PASS = #{pass, jdbcType=VARCHAR}

    /* 고객사  비밀번호 정책 로그인LOCK처리(Y) 로그인제한 체크  2020.09.16. */	

		SELECT NVL(A.LOCK_YN,'N') AS lock_yn 
          FROM CRM_CUST_EMP A 
         WHERE A.EMP_ID = #{emp_id, jdbcType=VARCHAR}

    /* 고객사 회원정보 비밀번호 정책 (C001 정책일수) 초과(Y) 체크  2020.09.15. */	

		SELECT CASE WHEN TRUNC(SYSDATE - (A.PASS_CHG_DATE + 1),0) > TO_NUMBER(Z.VAL1) THEN 'Y' ELSE 'N' END AS pass_policy1 
		      ,Z.VAL1 AS policy1_val 		
          FROM CRM_CUST_EMP A,    
               (SELECT VAL1 FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'COMMON' AND P_CODE = 'CD10' AND CODE = 'C001') Z      
         WHERE A.EMP_ID = #{emp_id, jdbcType=VARCHAR}

    /* 고객사 회원정보 비밀번호 정책 (C002 오류횟수제한) 로그인시 비밀번호 오류횟수제한(Y) 체크  2020.09.15. */	

		SELECT CASE WHEN A.LOGIN_F_CNT >= TO_NUMBER(Z.VAL1) THEN 'Y' ELSE 'N' END AS pass_policy2
		 	  ,Z.VAL1 AS policy2_val 
          FROM CRM_CUST_EMP A,     
               (SELECT VAL1 FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'COMMON' AND P_CODE = 'CD10' AND CODE = 'C002') Z      
         WHERE A.EMP_ID = #{emp_id, jdbcType=VARCHAR}

    /* 고객사 회원정보 비밀번호 정책 (C003 동일비번체크제한) 동일 비밀번호 체크제한(Y) 체크  2020.09.15. */	

		SELECT CASE WHEN COUNT(*) >= TO_NUMBER(Z.VAL1) THEN 'Y' ELSE 'N' END AS pass_policy3
		  	  ,Z.VAL1 AS policy3_val 
          FROM CRM_CUST_EMP_PASS_HIS A,    
               (SELECT VAL1 FROM CRM_CODE_DETAIL WHERE CODE_GROUP = 'COMMON' AND P_CODE = 'CD10' AND CODE = 'C003') Z      
         WHERE A.EMP_ID = #{emp_id, jdbcType=VARCHAR}
           AND A.PASS = #{pass, jdbcType=VARCHAR}	
        GROUP BY Z.VAL1

    /* 고객사 회원정보 비밀번호 정책 (C003 동일비번체크제한) 동일 비밀번호 체크제한(Y) 체크건수  2020.09.15. */	

		SELECT COUNT(*)
          FROM CRM_CUST_EMP_PASS_HIS  
         WHERE EMP_ID = #{emp_id, jdbcType=VARCHAR}
           AND PASS = #{pass, jdbcType=VARCHAR}

    /* 고객사 회원정보 비밀번호 정책 아이디 존재유무 체크건수  2020.09.15. */	

		SELECT COUNT(*) 
          FROM CRM_CUST_EMP  
         WHERE EMP_ID = #{emp_id, jdbcType=VARCHAR}

    /* 고객사 회원정보 비밀번호 정책 아이디/비번 체크건수  2020.09.15. */	

		SELECT COUNT(*) 
          FROM CRM_CUST_EMP
         WHERE EMP_ID = #{emp_id, jdbcType=VARCHAR}  
           AND PASS = #{pass, jdbcType=VARCHAR}
